-- =============================================================================
--  Migration 2: profile photo + location, 24/7 planning, friend suggestions,
--  email notifications.
--  Part A generated by `prisma migrate diff`; Part B hand-written.
-- =============================================================================

-- AlterTable
ALTER TABLE "profiles" ADD COLUMN     "avatar_url" VARCHAR(500),
ADD COLUMN     "city" VARCHAR(60),
ADD COLUMN     "region" VARCHAR(60);

-- AlterTable
ALTER TABLE "user_settings" ADD COLUMN     "discoverable" BOOLEAN NOT NULL DEFAULT true,
ALTER COLUMN "day_start_minute" SET DEFAULT 0,
ALTER COLUMN "day_end_minute" SET DEFAULT 1440;

-- AlterTable
ALTER TABLE "blocks" ADD COLUMN     "missed_sent_at" TIMESTAMPTZ(6),
ADD COLUMN     "reminder_sent_at" TIMESTAMPTZ(6);


-- ---------------------------------------------------------------------------
-- Part B
-- ---------------------------------------------------------------------------

alter table public.profiles
  add constraint profiles_avatar_https check (avatar_url is null or avatar_url ~ '^https://'),
  add constraint profiles_city_not_blank check (city is null or length(trim(city)) > 0),
  add constraint profiles_region_not_blank check (region is null or length(trim(region)) > 0);

-- Everyone plans 24/7 now (existing accounts included).
update public.user_settings set day_start_minute = 0, day_end_minute = 1440;

-- New profile columns: readable/updatable the same way as the others
-- (invite_code stays hidden).
grant select (avatar_url, city, region) on public.profiles to authenticated;
grant update (avatar_url, city, region) on public.profiles to authenticated;

-- One helper for creating friend requests, used by both public functions.
-- Not callable by users directly.
create function public.request_friendship(me uuid, them uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  existing public.friendships;
  new_id uuid;
begin
  if them = me then
    raise exception 'That''s you!' using errcode = '22023';
  end if;
  select * into existing from public.friendships f
  where least(f.requester_id, f.addressee_id) = least(me, them)
    and greatest(f.requester_id, f.addressee_id) = greatest(me, them);
  if found then
    -- They already asked me: accept instead of creating a duplicate.
    if existing.status = 'pending' and existing.addressee_id = me then
      update public.friendships set status = 'accepted', accepted_at = now() where id = existing.id;
    end if;
    return existing.id;
  end if;
  insert into public.friendships (requester_id, addressee_id) values (me, them) returning id into new_id;
  return new_id;
end $$;
revoke all on function public.request_friendship(uuid, uuid) from public, anon, authenticated;

-- send_friend_request(code) now reuses the helper.
create or replace function public.send_friend_request(code text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  them uuid;
begin
  if me is null then
    raise exception 'Not signed in' using errcode = '28000';
  end if;
  select id into them from public.profiles where invite_code = code;
  if them is null then
    raise exception 'Invite link not found' using errcode = 'P0002';
  end if;
  if them = me then
    raise exception 'That''s your own invite link' using errcode = '22023';
  end if;
  return public.request_friendship(me, them);
end $$;

-- PEOPLE YOU MAY KNOW
-- 1. Friends of your friends (with how many friends you share), then
-- 2. people in the same city and state/region.
-- Only people who left "discoverable" on, never anyone you're already
-- connected to, never yourself, and only public-ish fields.
create function public.suggest_friends(max_results integer default 10)
returns table (
  id uuid,
  display_name text,
  handle text,
  avatar_url text,
  avatar_color public.task_color,
  city text,
  region text,
  mutual_count integer,
  reason text
)
language sql stable security definer set search_path = '' as $$
  with me as (
    select (select auth.uid()) as id
  ),
  my_friends as (
    select case when f.requester_id = me.id then f.addressee_id else f.requester_id end as fid
    from public.friendships f, me
    where f.status = 'accepted' and me.id in (f.requester_id, f.addressee_id)
  ),
  connected as (
    select case when f.requester_id = me.id then f.addressee_id else f.requester_id end as cid
    from public.friendships f, me
    where me.id in (f.requester_id, f.addressee_id)
  ),
  friends_of_friends as (
    select case when f.requester_id = mf.fid then f.addressee_id else f.requester_id end as pid,
           count(*)::integer as mutual
    from public.friendships f
    join my_friends mf on mf.fid in (f.requester_id, f.addressee_id)
    where f.status = 'accepted'
    group by 1
  ),
  my_place as (
    select lower(trim(p.city)) as city, lower(trim(coalesce(p.region, ''))) as region
    from public.profiles p, me where p.id = me.id
  ),
  nearby as (
    select p.id as pid, 0 as mutual
    from public.profiles p, my_place
    where my_place.city is not null
      and lower(trim(p.city)) = my_place.city
      and lower(trim(coalesce(p.region, ''))) = my_place.region
  ),
  candidates as (
    select pid, max(mutual) as mutual from (
      select pid, mutual from friends_of_friends
      union all
      select pid, mutual from nearby
    ) c
    group by pid
  )
  select p.id, p.display_name::text, p.handle::text, p.avatar_url::text, p.avatar_color,
         p.city::text, p.region::text, c.mutual,
         case when c.mutual > 0 then 'mutual' else 'nearby' end
  from candidates c
  join public.profiles p on p.id = c.pid
  join public.user_settings s on s.user_id = p.id
  cross join me
  where me.id is not null
    and s.discoverable
    and p.id <> me.id
    and p.id not in (select cid from connected)
  order by c.mutual desc, p.display_name
  limit greatest(1, least(max_results, 50));
$$;

-- Send a request to someone from your suggestions (no invite link needed).
-- Only people who are actually suggested to you can be requested this way,
-- so this can't be used to spam arbitrary user ids.
create function public.send_friend_request_to(target uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'Not signed in' using errcode = '28000';
  end if;
  if not exists (select 1 from public.suggest_friends(50) s where s.id = target) then
    raise exception 'Person not found' using errcode = 'P0002';
  end if;
  return public.request_friendship(me, target);
end $$;

-- EMAIL NOTIFICATIONS
-- Called every few minutes by a trusted server job (service role only).
-- It CLAIMS what's due by stamping reminder_sent_at / missed_sent_at in the
-- same statement that finds it, so two overlapping runs can never email the
-- same thing twice (the second run sees the stamp and skips the row).
create function public.claim_notifications(at timestamptz default now())
returns table (
  kind text,
  block_id uuid,
  email text,
  display_name text,
  title text,
  starts_at timestamptz,
  ends_at timestamptz,
  time_zone text
)
language sql volatile security definer set search_path = '' as $$
  with upcoming as (
    update public.blocks b set reminder_sent_at = at
    from public.user_settings s
    where s.user_id = b.user_id
      and s.notify_upcoming
      and b.status = 'planned'
      and b.reminder_sent_at is null
      and b.starts_at > at
      and b.starts_at <= at + make_interval(mins => s.reminder_lead_minutes)
    returning 'upcoming'::text as kind, b.id, b.user_id, b.task_id, b.starts_at, b.ends_at
  ),
  missed as (
    update public.blocks b set missed_sent_at = at
    from public.user_settings s
    where s.user_id = b.user_id
      and s.notify_missed
      and b.status = 'planned'
      and b.missed_sent_at is null
      and b.ends_at <= at - interval '15 minutes'
      and b.ends_at > at - interval '1 day'
    returning 'missed'::text as kind, b.id, b.user_id, b.task_id, b.starts_at, b.ends_at
  ),
  due as (
    select * from upcoming union all select * from missed
  )
  select due.kind, due.id, u.email::text, p.display_name::text, t.title::text,
         due.starts_at, due.ends_at, s.time_zone::text
  from due
  join auth.users u on u.id = due.user_id
  join public.profiles p on p.id = due.user_id
  join public.tasks t on t.id = due.task_id
  join public.user_settings s on s.user_id = due.user_id
  where u.email is not null;
$$;

-- Who to email about a new friend request (service role only).
create function public.friend_request_email(friendship uuid)
returns table (email text, recipient_name text, requester_name text)
language sql stable security definer set search_path = '' as $$
  select u.email::text, them.display_name::text, me.display_name::text
  from public.friendships f
  join public.profiles me on me.id = f.requester_id
  join public.profiles them on them.id = f.addressee_id
  join public.user_settings s on s.user_id = f.addressee_id
  join auth.users u on u.id = f.addressee_id
  where f.id = friendship and f.status = 'pending' and s.notify_friends and u.email is not null;
$$;

revoke all on function public.suggest_friends(integer) from public, anon;
revoke all on function public.send_friend_request_to(uuid) from public, anon;
revoke all on function public.claim_notifications(timestamptz) from public, anon, authenticated;
revoke all on function public.friend_request_email(uuid) from public, anon, authenticated;
grant execute on function public.suggest_friends(integer) to authenticated;
grant execute on function public.send_friend_request_to(uuid) to authenticated;
grant execute on function public.claim_notifications(timestamptz) to service_role;
grant execute on function public.friend_request_email(uuid) to service_role;

-- PROFILE PHOTOS (Supabase Storage)
-- A public "avatars" bucket: anyone can VIEW a photo by URL, but you can only
-- upload/replace/delete files inside a folder named after your own user id.
-- Skipped automatically where Supabase Storage doesn't exist (tests).
do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'storage') then
    begin
      insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
      values ('avatars', 'avatars', true, 1048576, array['image/jpeg', 'image/png', 'image/webp'])
      on conflict (id) do nothing;

      execute $p$create policy "avatars: read own" on storage.objects for select to authenticated
        using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text)$p$;
      execute $p$create policy "avatars: upload own" on storage.objects for insert to authenticated
        with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text)$p$;
      execute $p$create policy "avatars: replace own" on storage.objects for update to authenticated
        using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text)
        with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text)$p$;
      execute $p$create policy "avatars: delete own" on storage.objects for delete to authenticated
        using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text)$p$;
    exception when insufficient_privilege or duplicate_object then
      raise notice 'Storage policies not created here (%). Create the avatars bucket in the dashboard; see DATABASE.md.', sqlerrm;
    end;
  end if;
end $$;
